    id: "bankrbot-endaoment",
    name: "Endaoment",
    description: "Donate to charities onchain via Endaoment. USDC donations or auto-swap from ETH/tokens. Base, Ethereum, Optimism.",
    identifier: "BankrBot/skills/endaoment",
    source: "github",
