    id: "bankrbot-gitlawb",
    name: "GitLawb",
    description: "Decentralized git for AI agents and humans. Repos, PRs, issues, on-chain bounties, agent delegation, DID identity.",
    identifier: "BankrBot/skills/gitlawb",
    source: "github",
