    id: "bankrbot-symbiosis",
    name: "Symbiosis",
    description: "Cross-chain token swaps across 54+ blockchains via Symbiosis. Any-to-any swaps with automatic routing, executed via Bankr.",
    identifier: "BankrBot/skills/symbiosis",
    source: "github",
